#include <zephyr/kernel.h>
#include <zephyr/lib/cobs.h>
#include <string.h>

void cobs_decode_ctx_init(struct cobs_decode_ctx *ctx)
{
    ctx->state = COBS_DECODE_STATE_START;
    ctx->code = 0;
    ctx->ptr = 0;
    ctx->out_idx = 0;
}

enum cobs_decode_return cobs_decode_stream(struct cobs_decode_ctx *ctx,
                                           const uint8_t *in_buf, size_t in_len,
                                           uint8_t *out_buf, size_t out_max_len,
                                           size_t *consumed_in_len, size_t *produced_out_len)
{
    size_t in_idx = 0;
    enum cobs_decode_return ret = COBS_DECODE_IN_PROGRESS;

    *consumed_in_len = 0;
    *produced_out_len = 0;

    while (in_idx < in_len) {
        uint8_t byte = in_buf[in_idx];

        if (ctx->state == COBS_DECODE_STATE_START) {
            if (byte == 0x00) {
                ret = COBS_DECODE_ERROR_UNEXPECTED_ZERO;
                goto end;
            }
            ctx->code = byte;
            ctx->ptr = byte; /* ptr is the count of bytes remaining in this block, including the next code/delimiter */
            ctx->state = COBS_DECODE_STATE_DATA;
            in_idx++;
            continue;
        }

        if (ctx->state == COBS_DECODE_STATE_DATA) {
            if (ctx->ptr == 1) {
                /* The current block is complete. The next byte is the new code byte or 0x00 delimiter. */
                ctx->state = COBS_DECODE_STATE_CODE_BYTE;
                /* Do not increment in_idx here, the current byte will be processed in the next state. */
                continue;
            }

            if (byte == 0x00) {
                ret = COBS_DECODE_ERROR_UNEXPECTED_ZERO;
                goto end;
            }

            if (ctx->out_idx >= out_max_len) {
                ret = COBS_DECODE_ERROR_OVERRUN;
                goto end;
            }

            out_buf[ctx->out_idx++] = byte;
            ctx->ptr--;
            in_idx++;
        } else if (ctx->state == COBS_DECODE_STATE_CODE_BYTE) {
            if (byte == 0x00) {
                /* Delimiter found. Frame complete. */
                *produced_out_len = ctx->out_idx;
                *consumed_in_len = in_idx + 1; /* Consume the 0x00 */
                cobs_decode_ctx_init(ctx); /* Reset context for next frame */
                ret = COBS_DECODE_FRAME_COMPLETE;
                goto end;
            }

            /* New code byte */
            ctx->code = byte;
            ctx->ptr = byte;
            ctx->state = COBS_DECODE_STATE_DATA;
            in_idx++;
        }
    }

end:
    if (ret == COBS_DECODE_IN_PROGRESS) {
        *consumed_in_len = in_idx;
    }
    return ret;
}
